import React, { useEffect, useState } from "react";
import { getFiles } from "../services/api";
import { Line, Bar } from "react-chartjs-2";
import { Activity } from "lucide-react";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  BarElement,
  Tooltip,
  Legend
} from "chart.js";

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  BarElement,
  Tooltip,
  Legend
);

const green = "#00ff9d";
const purple = "#a855f7";

const Performance = () => {
  const [files, setFiles] = useState([]);

  useEffect(() => {
    const load = async () => {
      try {
        const res = await getFiles();
        setFiles(res.data || []);
      } catch {}
    };
    load();
  }, []);

  // ================= SAFE =================
  const getTotal = f => f?.metrics?.total_ms ?? f?.metrics?.total ?? 0;

  // ================= LABELS =================
  const labels = files.map(f =>
    f.filename.length > 14 ? f.filename.slice(0, 14) + "..." : f.filename
  );

  // ================= DATA =================
  const pqcData = files.map(f => (f.mode === "hybrid" ? getTotal(f) : null));
  const rsaData = files.map(f => (f.mode !== "hybrid" ? getTotal(f) : null));

  // ================= AVG =================
  const hybrid = files.filter(f => f.mode === "hybrid");
  const rsa = files.filter(f => f.mode !== "hybrid");

  const avgPqc = hybrid.length
    ? (hybrid.reduce((a, f) => a + getTotal(f), 0) / hybrid.length).toFixed(2)
    : "0.00";

  const avgRsa = rsa.length
    ? (rsa.reduce((a, f) => a + getTotal(f), 0) / rsa.length).toFixed(2)
    : "0.00";

  // ================= TIMELINE =================
  const lineChartData = {
    labels,
    datasets: [
      {
        label: "Hybrid PQC",
        data: pqcData,
        borderColor: green,
        backgroundColor: green,
        tension: 0.4,
        spanGaps: true
      },
      {
        label: "RSA Baseline",
        data: rsaData,
        borderColor: purple,
        backgroundColor: purple,
        tension: 0.4,
        spanGaps: true
      }
    ]
  };

  return (
    <div className="p-8 space-y-6 overflow-y-auto custom-scrollbar">
      {/* HEADER */}
      <div className="flex justify-between items-center border-b border-gray-800 pb-4">
        <div>
          <h2 className="text-2xl font-bold text-white">Performance Monitor</h2>
          <p className="text-gray-500 text-xs font-mono uppercase">
            Comparative Analysis Engine
          </p>
        </div>

        <div className="text-right">
          <span className="text-xs text-gray-500 uppercase">Total Files</span>
          <p className="text-2xl font-mono text-white">{files.length}</p>
        </div>
      </div>

      {/* GRAPH */}
      <div className="bg-scifi-panel border border-scifi-border p-6 rounded-xl">
        <h3 className="text-gray-400 text-xs uppercase mb-6 flex gap-2 items-center">
          <Activity size={16} className="text-neon-blue" />
          Encryption Timeline
        </h3>

        <div className="h-72">
          <Line
            data={lineChartData}
            options={{
              responsive: true,
              maintainAspectRatio: false,
              plugins: {
                legend: { labels: { color: "#fff" } },
                tooltip: {
                  callbacks: {
                    title: ctx => files[ctx[0].dataIndex]?.filename
                  }
                }
              }
            }}
          />
        </div>
      </div>

      {/* AVERAGES */}
      <div className="grid grid-cols-2 gap-4">
        <Card title="Average PQC" value={avgPqc} color={green} />
        <Card title="Average RSA" value={avgRsa} color={purple} />
      </div>

      {/* PER FILE */}
      <div className="space-y-3">
        {files.map(f => (
          <div key={f.id} className="bg-black/40 border border-gray-800 p-4 rounded">
            <div className="flex justify-between">
              <span className="text-white font-bold">{f.filename}</span>
              <span style={{ color: f.mode === "hybrid" ? green : purple }}>
                {f.mode}
              </span>
            </div>

            <div className="mt-2 text-xs font-mono text-gray-400">
              Total → <span className="text-white">{getTotal(f)} ms</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

const Card = ({ title, value, color }) => (
  <div className="bg-black/40 border border-gray-800 p-4 rounded flex justify-between">
    <span className="text-gray-400">{title}</span>
    <span style={{ color }} className="font-bold">{value} ms</span>
  </div>
);

export default Performance;
